from research_sdk import Client
import json, time
c = Client()
jobs = json.load(open('/workspace/work/full_jobs.json'))
jid = jobs['development-01']
deadline = time.time() + 600
while time.time() < deadline and c.status(jid)['status'] in ('queued','running'):
    time.sleep(15)
res = c.status(jid)
print('dev-01:', res['status'])
if res.get('result') and res['result'].get('items'):
    items = res['result']['items']
    json.dump({'model':'development-01','items':items}, open('/workspace/work/full_01.json','w'), indent=1)
    qs = {q['id']: q['domain'] for q in json.load(open('/workspace/submission/assets/questions.json'))}
    import collections
    bydom = collections.defaultdict(list)
    for it in items:
        if it.get('score') is not None:
            bydom[qs[it['id']]].append(it['score'])
    for d in ['coding','co-work','reasoning']:
        v = bydom[d]
        print(f"  {d}: n={len(v)} mean={sum(v)/len(v):.3f} distinct={len(set(round(x,3) for x in v))}")
    print("  items scoring < 1.0:")
    for it in items:
        if it.get('score') is not None and it['score'] < 1.0:
            print(f"    {it['id']:14s} {it['score']:.2f} {it.get('finish_reason')}")
EOF",
  "description": "Wait for dev-01 with cutoff and analyze"
}

